import { router } from 'expo-router';

import { friendlyError, supabase } from '@/lib/supabase';
import type { GameSession } from '@/lib/types';

/** Creates a game session (lobby) for a quiz and opens the host view. Returns an error message on failure. */
export async function startSession(quizId: string): Promise<string | null> {
  // join_code is generated by the database (generate_join_code()).
  const { data, error } = await supabase
    .from('game_sessions')
    .insert({ quiz_id: quizId })
    .select()
    .single();
  if (error) return friendlyError(error);
  router.push({ pathname: '/host/session/[id]', params: { id: (data as GameSession).id } });
  return null;
}
